import requests
from agents import function_tool


def _build_blocks(title, body, tags):
    blocks = [
        {"type": "header", "text": {"type": "plain_text", "text": title[:150]}},
        {"type": "section", "text": {"type": "mrkdwn", "text": body[:2900] or "_(empty note)_"}},
    ]
    if tags:
        tag_line = " ".join(f"`#{t}`" for t in tags)
        blocks.append({"type": "context", "elements": [{"type": "mrkdwn", "text": tag_line}]})
    return blocks


@function_tool
def post_note_to_slack(webhook_url: str, title: str, body: str, tags: list[str] | None = None) -> str:
    if not webhook_url.startswith("https://hooks.slack.com/"):
        return "Rejected: not a Slack webhook URL."
    payload = {"text": title, "blocks": _build_blocks(title, body, tags or [])}
    resp = requests.post(webhook_url, json=payload, timeout=10)
    if resp.status_code != 200:
        return f"Slack returned {resp.status_code}: {resp.text}"
    truncated = len(body) > 2900
    return "Posted note to Slack" + (" (body truncated)." if truncated else ".")
